/*
 * Command.
 *
 * The palette is a SCREEN, not a search box. The query line sits in the
 * LcdChip's recessed well, in the LCD voice, with an emissive caret and a
 * scanline wash over it — so summoning it reads as waking the device's readout.
 * The results below are on the chassis, in the machine voice, so the screen and
 * the panel stay two different materials.
 *
 * Composes var(--echo-*) only.
 */

.echo-command__backdrop {
  position: fixed;
  z-index: var(--echo-z-overlay, 200); /* Modal's scale; the site chrome's sticky rail is at 40. */
  inset: 0;
  background: color-mix(in oklab, var(--echo-seam) 88%, black);
  opacity: 0.72;
  transition: opacity var(--echo-duration-swap) ease;
}

.echo-command__backdrop[data-starting-style],
.echo-command__backdrop[data-ending-style] {
  opacity: 0;
}

.echo-command__popup {
  position: fixed;
  z-index: var(--echo-z-modal, 210);
  top: 14vh;
  left: 50%;
  box-sizing: border-box;
  width: min(38rem, calc(100vw - 2.5rem));
  max-height: 68vh;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  padding: var(--echo-space-5);
  border-radius: var(--echo-radius-2xl);
  transform: translateX(-50%);
  background: linear-gradient(158deg, var(--echo-cap) 0%, var(--echo-surface) 40%);
  outline: none;
  box-shadow:
    inset 0 1px 0 color-mix(in oklab, var(--echo-cap-highlight) 46%, transparent),
    inset 0 0 0 1px var(--echo-seam),
    0 44px 90px -26px color-mix(in oklab, var(--echo-cast-ink, black) calc(0.85 * var(--echo-shade, 1) * 100%), transparent);
  transition:
    opacity var(--echo-duration-swap) ease,
    transform var(--echo-duration-swap) cubic-bezier(0.16, 1, 0.3, 1);
}

.echo-command__popup[data-starting-style],
.echo-command__popup[data-ending-style] {
  opacity: 0;
  transform: translateX(-50%) scale(0.97) translateY(-8px);
}
/* With motion running (usePopupMotion), GSAP draws the arrival and exit. */
.echo-command__popup[data-motion],
.echo-command__popup[data-motion][data-starting-style],
.echo-command__popup[data-motion][data-ending-style] {
  opacity: 1;
  transform: translateX(-50%);
  transition: none;
}

/* --- the query line: an LCD well ---------------------------------------- */

.echo-command__bar {
  position: relative;
  display: flex;
  align-items: center;
  gap: var(--echo-space-5);
  flex: none;
  padding: 0 var(--echo-space-7);
  border-radius: var(--echo-radius-lg);
  background: var(--echo-drawn-glass, linear-gradient(160deg, var(--echo-well) 0%, var(--echo-lcd) 100%));
  box-shadow:
    inset 0 2px 6px color-mix(in oklab, var(--echo-cast-ink, black) calc(0.85 * var(--echo-shade, 1) * 100%), transparent),
    inset 0 -1px 0 rgb(255 255 255 / calc(0.05 * var(--echo-gloss, 1))),
    inset 0 0 0 var(--echo-line-width, 0px) var(--echo-line, transparent);
}

/*
 * The dot matrix. A repeating-gradient scanline wash over the screen well —
 * the same idea as the `scanlines` texture, inlined here so the item does not
 * take a dependency on echo-textures for four lines of CSS.
 */
.echo-command__bar::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  pointer-events: none;
  opacity: 0.5;
  background: repeating-linear-gradient(
    0deg,
    color-mix(in oklch, var(--echo-accent-glow) 7%, transparent) 0 1px,
    transparent 1px 3px
  );
}

.echo-command__caret {
  flex: none;
  font-family: var(--echo-font-lcd, ui-monospace, SFMono-Regular, Menlo, monospace);
  font-size: var(--echo-text-lg);
  line-height: var(--echo-leading-none, 1);
  /* Emissive LCD glyph — the same lit accent as StatTile and LcdChip. */
  color: var(--echo-accent-ink, var(--echo-accent-glow));
  text-shadow: 0 0 10px color-mix(in oklab, var(--echo-lcd-glow) 50%, transparent);
}

.echo-command__input {
  width: 100%;
  height: calc(50px * var(--echo-density, 1));
  border: 0;
  outline: none;
  background: transparent;
  color: var(--echo-text);
  caret-color: var(--echo-accent-glow);
  font-family: var(--echo-font-lcd, ui-monospace, SFMono-Regular, Menlo, monospace);
  font-size: var(--echo-text-md);
  letter-spacing: var(--echo-tracking-normal, 0);
}

.echo-command__input::placeholder {
  color: var(--echo-text-dim);
}

/* --- results: on the chassis, not on the screen -------------------------- */

.echo-command__list {
  flex: 1 1 auto;
  min-height: 0;
  overflow-y: auto;
  overscroll-behavior: contain;
  padding: var(--echo-space-3) 0 var(--echo-space-1);
  scrollbar-width: thin;
  scrollbar-color: var(--echo-cap) transparent;
}

.echo-command__group + .echo-command__group {
  margin-top: var(--echo-space-1);
}

.echo-command__group-label {
  padding: var(--echo-space-5) var(--echo-space-6) var(--echo-space-3);
  font-family: var(--echo-font-machine, ui-sans-serif, system-ui, sans-serif);
  font-size: var(--echo-text-3xs);
  font-weight: var(--echo-weight-bold, 700);
  letter-spacing: var(--echo-tracking-label, 0.2em);
  text-transform: uppercase;
  color: var(--echo-text-dim);
}

.echo-command__item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--echo-space-7);
  padding: var(--echo-space-5) var(--echo-space-6);
  border-radius: var(--echo-radius-md);
  cursor: default;
  user-select: none;
  outline: none;
  font-family: var(--echo-font-machine, ui-sans-serif, system-ui, sans-serif);
  font-size: var(--echo-text-sm);
  color: var(--echo-text-dim);
}

/*
 * The armed row carries an accent RAIL, not accent text: accent on the chassis
 * is 3.70:1, under AA. The rail says "this one" without asking the label to
 * carry the colour — the same fix Echo uses for accent links.
 */
.echo-command__item[data-highlighted] {
  position: relative;
  background: color-mix(in oklab, var(--echo-text) 8%, transparent);
  color: var(--echo-text);
}

.echo-command__item[data-highlighted]::before {
  content: "";
  position: absolute;
  inset-inline-start: 3px;
  top: 7px;
  bottom: 7px;
  width: 2px;
  border-radius: var(--echo-radius-xs);
  background: var(--echo-accent-glow);
  box-shadow: 0 0 8px color-mix(in oklch, var(--echo-accent-glow) 70%, transparent);
}

.echo-command__item[data-disabled] {
  opacity: 0.42;
  cursor: not-allowed;
}

.echo-command__label {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.echo-command__hint {
  flex: none;
  font-family: var(--echo-font-machine, ui-sans-serif, system-ui, sans-serif);
  font-size: var(--echo-text-2xs);
  letter-spacing: var(--echo-tracking-wide, 0.06em);
  color: var(--echo-text-dim);
}

/*
 * Base UI keeps the Empty element mounted and simply blanks its content when
 * there ARE results, so its padding was leaving 52px of dead space above the
 * first group. Collapsing the padding rather than `display: none` keeps it in
 * the accessibility tree, which is where it announces "no results" from.
 */
.echo-command__empty:empty {
  padding: 0;
}

.echo-command__empty {
  padding: var(--echo-space-10) var(--echo-space-6);
  text-align: center;
  font-family: var(--echo-font-machine, ui-sans-serif, system-ui, sans-serif);
  font-size: var(--echo-text-sm);
  color: var(--echo-text-dim);
}

@media (prefers-reduced-motion: reduce) {
  .echo-command__popup {
    transition-duration: var(--echo-duration-glitch);
  }
  .echo-command__popup[data-starting-style],
  .echo-command__popup[data-ending-style] {
    transform: translateX(-50%);
  }
}

"use client";

/**
 * Command. The command palette,
 * as a dot-matrix readout you type into.
 *
 * WHY AUTOCOMPLETE AND NOT COMBOBOX. Base UI is explicit: Combobox is a
 * filterable Select whose input is restricted to the item set, and it points
 * search widgets at Autocomplete — which documents "filterable command pickers"
 * as its own use case. A palette takes free-form text and runs an action; it
 * does not hold a value. Combobox would have been the wrong semantics wearing
 * the right shape.
 *
 * WHY A DIALOG AROUND IT. Autocomplete anchors its list to the input. A palette
 * is not anchored to anything — it is summoned to the middle of the screen. So
 * Dialog owns the frame (backdrop, focus trap, Escape, scroll lock) and
 * Autocomplete owns the input, the filtering and the listbox semantics inside
 * it. `Autocomplete.List` falls back to being its own positioner when there is
 * no Positioner above it, which is what makes the inline list legal rather than
 * a hack.
 *
 * THE SKIN. The input sits in the LcdChip's recessed screen well, in the LCD
 * voice, with an emissive caret — so the palette reads as the device's readout
 * rather than as a web search box. That is the whole point of the item: a
 * command bar in this vocabulary is something no other library's version feels
 * like.
 *
 * NOTE: the package is `@base-ui/react`, NOT `@base-ui-components/react`.
 */
import { useCallback, useEffect, useMemo, useState, type ReactNode } from "react";
import { Dialog } from "@base-ui/react/dialog";
import { Autocomplete } from "@base-ui/react/autocomplete";
import type { EchoPortalContainer } from "echo-ui-core/types";
import { useSoundOptional } from "echo-ui-core/sound";
import { liquidBloom, usePopupMotion } from "echo-ui-core/presence";
import "./command.css";

export interface CommandItem {
  /** Stable identity. Also what `onRun` receives. */
  id: string;
  /** What the command is called. The primary thing matched and read. */
  label: string;
  /** Trailing hint — a shortcut, a destination, a current value. */
  hint?: string;
  /**
   * Extra words that should match this command without being shown. "trash"
   * finding "Delete take" is the difference between a palette people use and
   * one they give up on.
   */
  keywords?: string[];
  disabled?: boolean;
  /** Run it. The palette closes first, so this can open another surface. */
  run?: () => void;
}

export interface CommandGroup {
  label: string;
  items: CommandItem[];
}

export interface CommandProps {
  /** Grouped commands. Groups keep their order; items are filtered within them. */
  groups: CommandGroup[];
  open?: boolean;
  onOpenChange?: (open: boolean) => void;
  /**
   * Bind a global hotkey. Default "k" (with Cmd on Apple, Ctrl elsewhere).
   * Pass null for no binding — the right choice when the app owns its
   * shortcuts, or when two palettes could otherwise answer one keystroke.
   */
  shortcut?: string | null;
  placeholder?: string;
  /** Shown when nothing matches. Say what would help, not just "no results". */
  emptyMessage?: ReactNode;
  /** Fired with the item that was run, after the palette closes. */
  onRun?: (item: CommandItem) => void;
  /**
   * Where the palette mounts. Defaults to <body>. Pass an element inside a
   * scoped theme (`createEchoTheme(seed, { selector })`) and the palette wears
   * that theme too — mounted on <body>, it can only read the :root one.
   */
  container?: EchoPortalContainer;
}

/** Everything a query should match against, joined once per item. */
const searchText = (item: CommandItem) =>
  [item.label, item.hint, ...(item.keywords ?? [])].filter(Boolean).join(" ").toLowerCase();

export function Command({
  groups,
  open: controlledOpen,
  onOpenChange,
  shortcut = "k",
  placeholder = "Type a command…",
  emptyMessage = "No commands match.",
  onRun,
  container,
}: CommandProps) {
  const [uncontrolledOpen, setUncontrolledOpen] = useState(false);
  const open = controlledOpen ?? uncontrolledOpen;
  const [query, setQuery] = useState("");
  const sound = useSoundOptional();

  const setOpen = useCallback(
    (next: boolean) => {
      if (controlledOpen === undefined) setUncontrolledOpen(next);
      onOpenChange?.(next);
    },
    [controlledOpen, onOpenChange],
  );

  // The global hotkey. Bound on the document so it works wherever focus is,
  // which is the entire proposition of a palette.
  useEffect(() => {
    if (!shortcut) return;
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key.toLowerCase() !== shortcut.toLowerCase()) return;
      // metaKey on Apple, ctrlKey everywhere else — accepting either would
      // swallow Ctrl+K (delete-to-end-of-line) on macOS.
      if (!event.metaKey && !event.ctrlKey) return;
      event.preventDefault();
      setOpen(!open);
    };
    document.addEventListener("keydown", onKeyDown);
    return () => document.removeEventListener("keydown", onKeyDown);
  }, [shortcut, open, setOpen]);

  /*
   * Filtering is done here rather than by Base UI's own filter so that
   * `keywords` count — an item has to match on words it never displays. Groups
   * that end up empty are dropped, because a heading over nothing reads as a
   * rendering bug.
   */
  const filtered = useMemo(() => {
    const q = query.trim().toLowerCase();
    if (!q) return groups;
    return groups
      .map((group) => ({ ...group, items: group.items.filter((i) => searchText(i).includes(q)) }))
      .filter((group) => group.items.length > 0);
  }, [groups, query]);

  const runItem = useCallback(
    (item: CommandItem) => {
      if (item.disabled) return;
      sound?.play("select");
      // Close BEFORE running: a command that opens another dialog would
      // otherwise race this one's exit and lose the focus trap.
      setOpen(false);
      setQuery("");
      item.run?.();
      onRun?.(item);
    },
    [onRun, setOpen, sound],
  );

  // Liquid bloom, the same arrival as Modal: out of a pill in the middle.
  const bloom = usePopupMotion(liquidBloom);

  return (
    <Dialog.Root
      open={open}
      onOpenChange={(next) => {
        if (next) sound?.play("transition");
        else setQuery("");
        setOpen(next);
      }}
    >
      <Dialog.Portal container={container}>
        <Dialog.Backdrop className="echo-command__backdrop" />
        <Dialog.Popup
          ref={bloom}
          className="echo-command__popup"
          aria-label="Command palette"
          /*
           * Escape has to close the PALETTE. Autocomplete's own Escape closes
           * its list — and the list here is forced open, so it handles the key
           * and nothing happens, leaving a modal with no keyboard way out.
           * Capture runs before Autocomplete sees it.
           */
          onKeyDownCapture={(event) => {
            if (event.key !== "Escape") return;
            event.preventDefault();
            event.stopPropagation();
            setQuery("");
            setOpen(false);
          }}
        >
          <Autocomplete.Root
            items={filtered}
            value={query}
            onValueChange={setQuery}
            // Always open: inside the palette the list IS the palette, so there
            // is nothing for a closed state to mean.
            open
            // The first match is armed, so Enter runs the obvious thing without
            // an arrow press. `mode="none"` keeps it from rewriting the query.
            autoHighlight="always"
            mode="none"
            itemToStringValue={(item: CommandItem) => item.label}
          >
            <div className="echo-command__bar">
              <span className="echo-command__caret" aria-hidden="true">
                ›
              </span>
              <Autocomplete.Input
                className="echo-command__input"
                placeholder={placeholder}
                aria-label="Search commands"
              />
            </div>

            <Autocomplete.Empty className="echo-command__empty">{emptyMessage}</Autocomplete.Empty>

            <Autocomplete.List className="echo-command__list">
              {(group: CommandGroup) => (
                <Autocomplete.Group
                  key={group.label}
                  items={group.items}
                  className="echo-command__group"
                >
                  <Autocomplete.GroupLabel className="echo-command__group-label">
                    {group.label}
                  </Autocomplete.GroupLabel>
                  <Autocomplete.Collection>
                    {(item: CommandItem) => (
                      <Autocomplete.Item
                        key={item.id}
                        value={item}
                        disabled={item.disabled}
                        className="echo-command__item"
                        onClick={() => runItem(item)}
                      >
                        <span className="echo-command__label">{item.label}</span>
                        {item.hint ? (
                          <span className="echo-command__hint">{item.hint}</span>
                        ) : null}
                      </Autocomplete.Item>
                    )}
                  </Autocomplete.Collection>
                </Autocomplete.Group>
              )}
            </Autocomplete.List>
          </Autocomplete.Root>
        </Dialog.Popup>
      </Dialog.Portal>
    </Dialog.Root>
  );
}
